listing = boundary retry 2 {
    return list_orders({ month: "2026-03", page: 1 })
} catch err {
    return fail("LIST_FAILED", err.code + ": " + err.message)
}
remaining = for page in list.range(2, listing.total_pages + 1) {
    result = boundary retry 2 { return list_orders({ month: "2026-03", page: page }) } catch err {
        return fail("LIST_FAILED", err.code + ": " + err.message)
    }
    return result.items
}
orders = fold acc = listing.items for page_items in remaining {
    return acc + page_items
}
region_amounts = for o in orders {
    detail = get_order({ id: o.id })
    skip if detail.status != "completed"
    customer = get_customer({ id: o.customer_id })
    return { region: customer.region, amount: detail.amount_cents }
}
totals = fold acc = { NA: 0, EU: 0, APAC: 0 } for row in region_amounts {
    return acc + { [row.region]: acc[row.region] + row.amount }
}
submitted = submit_result({ answer: totals })
return { totals: totals, submitted: submitted }

listing = boundary retry 2 {
    return list_orders({ month: "2026-03", page: 1 })
} catch err {
    return fail("LIST_FAILED", err.code + ": " + err.message)
}
remaining = for page in list.range(2, listing.total_pages + 1) {
    result = boundary retry 2 { return list_orders({ month: "2026-03", page: page }) } catch err {
        return fail("LIST_FAILED", err.code + ": " + err.message)
    }
    return result.items
}
orders = fold acc = listing.items for page_items in remaining {
    return acc + page_items
}
region_amounts = for o in orders {
    detail = get_order({ id: o.id })
    skip if detail.status != "completed"
    cust_id = o.customer_id if o.customer_id != null else detail.customer_id
    customer = get_customer({ id: cust_id })
    amt = detail.amount_cents if detail.amount_cents != null else 0
    return { region: customer.region, amount: amt }
}
totals = fold acc = { NA: 0, EU: 0, APAC: 0 } for row in region_amounts {
    r = row.region
    prev = acc[r] if r in acc else 0
    return acc + { [r]: prev + row.amount }
}
return { order_count: list.length(orders), completed: list.length(region_amounts), totals: totals }
